60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Minimal syntactic check for an email address: a non-empty local part, a single
66	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final TelephoneNormalizer telephoneNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 AddressNormalizer addressNormalizer) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
130	        LocalDate registrationDate = owner.getRegistrationDate();
131	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
132	            .map(Owner::getRegistrationDate)
133	            .filter(registrationDate::equals)
134	            .count();
135	        if (ownersCreatedThatDay >= 100) {
136	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
137	        }
138	        String address = addressNormalizer.normalize(owner.getAddress());
139	        if (address.isBlank()) {
140	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
141	        }
142	        owner.setAddress(address);
143	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
144	        if (telephone == null) {
145	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
146	        }
147	        owner.setTelephone(telephone);
148	        String email = owner.getEmail();
149	        if (email != null) {
150	            email = email.trim();
151	            if (!EMAIL_PATTERN.matcher(email).matches()) {
152	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	            }
154	            owner.setEmail(email.toLowerCase(Locale.ROOT));
155	        }
156	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
157	            .map(Owner::getTelephone)
158	            .filter(Objects::nonNull)
159	            .map(telephoneNormalizer::normalize)
160	            .anyMatch(telephone::equals);
161	        if (telephoneInUse) {
162	            return new ResponseEntity<>(HttpStatus.CONFLICT);
163	        }
164	        String cityKey = normalizeIdentity(owner.getCity());
165	        long ownersInCity = this.clinicService.findAllOwners().stream()
166	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
167	            .count();
168	        if (ownersInCity >= 50) {
169	            return new ResponseEntity<>(HttpStatus.CONFLICT);
170	        }
171	        String lastNameKey = normalizeIdentity(owner.getLastName());
172	        String addressKey = addressNormalizer.normalize(owner.getAddress());
173	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
174	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
175	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
176	                    && addressNormalizer.normalize(existing.getAddress()).equals(addressKey));
177	            if (householdDuplicate) {
178	                return new ResponseEntity<>(HttpStatus.CONFLICT);
179	            }
180	        }
181	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
182	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
183	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
184	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
185	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
186	            .count();
187	        owner.setNamesakeCount(namesakeCount);
188	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
189	        this.clinicService.saveOwner(owner);
190	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
191	        headers.setLocation(UriComponentsBuilder.newInstance()
192	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
193	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
194	    }
