196	    /**
197	     * Normalize a value for household-identity comparison: null becomes an empty
198	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
199	     * to a single space, and the result is lower-cased.
200	     */
201	    private static String normalizeIdentity(String value) {
202	        if (value == null) {
203	            return "";
204	        }
205	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
206	    }
207	
208	    /**
209	     * Build the stable, shared household identifier for an owner, formatted
210	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
211	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
212	     * Owners in the same household (same normalized lastName and address) therefore
213	     * derive an identical householdId.
214	     */
215	    private static String householdId(String lastNameKey, String addressKey) {
216	        String source = lastNameKey + "|" + addressKey;
217	        try {
218	            byte[] digest = MessageDigest.getInstance("SHA-256")
219	                .digest(source.getBytes(StandardCharsets.UTF_8));
220	            StringBuilder sb = new StringBuilder(digest.length * 2);
221	            for (byte b : digest) {
222	                sb.append(String.format("%02x", b));
223	            }
224	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
225	        }
226	        catch (NoSuchAlgorithmException e) {
227	            throw new IllegalStateException("SHA-256 not available", e);
228	        }
229	    }
230	
231	    /**
232	     * Build the customer code assigned on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}:
233	     * CITY3 is the upper-cased first three letters of {@code city}, LAST3 is the upper-cased
234	     * first three letters of {@code lastName} and NNNN is a per-city 4-digit zero-padded
235	     * sequence equal to one more than the number of owners already in that city
236	     * (e.g. 'LON-SMI-0007').
237	     */
238	    private String nextCustomerCode(String city, String lastName) {
239	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
240	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
241	        String cityKey = normalizeIdentity(city);
242	        int sequence = (int) this.clinicService.findAllOwners().stream()
243	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(cityKey))
244	            .count() + 1;
245	        return String.format("%s-%s-%04d", city3, last3, sequence);
246	    }
247	
248	    /**
249	     * Roll a registration date forward to the next business day: a Saturday or Sunday
250	     * advances to the following Monday, and a weekday is returned unchanged.
251	     */
252	    private static LocalDate toBusinessDay(LocalDate date) {
253	        return switch (date.getDayOfWeek()) {
254	            case SATURDAY -> date.plusDays(2);
255	            case SUNDAY -> date.plusDays(1);
256	            default -> date;
257	        };
258	    }
259	
260	    /**
261	     * Build the membership number assigned on create, formatted
262	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the
263	     * {@code registrationDate} year (e.g. 'LON-SMI-0007-M26').
264	     */
265	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
266	        String yy = String.format("%02d", registrationDate.getYear() % 100);
267	        return customerCode + "-M" + yy;
268	    }
